<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class CommitteeCommitment extends Model{protected $fillable=['committee_id','meeting_id','agenda_item_id','annual_work_plan_item_id','description','responsible_employee_id','due_date','priority','status','progress','completed_at','evidence_path','notes','created_by'];protected $casts=['due_date'=>'date','completed_at'=>'datetime'];public function responsible(){return $this->belongsTo(Empleado::class,'responsible_employee_id');}public function followups(){return $this->hasMany(CommitteeCommitmentFollowup::class,'commitment_id')->orderBy('followup_date');}public function getIsOverdueAttribute(){return $this->due_date?->isPast()&&!in_array($this->status,['completed','cancelled']);}}
